module schetchik
(
// {{ALTERA_ARGS_BEGIN}} DO NOT REMOVE THIS LINE!
C, R, D, Q
// {{ALTERA_ARGS_END}} DO NOT REMOVE THIS LINE!
);
// Port Declaration

// {{ALTERA_IO_BEGIN}} DO NOT REMOVE THIS LINE!
input C;
input R;
input [3:0] D;
output [3:0] Q;
// {{ALTERA_IO_END}} DO NOT REMOVE THIS LINE!

// Блок schetchik: 4-разрядный счётчик Джонсона (вариант 2).
// Состояния Q3..Q0: 0000,0001,0011,0111,1111,1110,1100,1000.
// D[3..0] - переключатели SW9..SW6: на них набирается следующее
// состояние (то, что подаётся на D-входы триггеров).
// По нему блок определяет текущее состояние счётчика Q.
// R - сброс (1 = Q обнуляется). C - вход синхросигнала (PIN_F15).
// Запрещённые коды D -> Q = 0101 (все светодиоды погашены).
reg [3:0] Q;

always @(C or R or D)
    if (R)
        Q = 4'b0000;
    else
        case (D)
            4'b0001 : Q = 4'b0000;
            4'b0011 : Q = 4'b0001;
            4'b0111 : Q = 4'b0011;
            4'b1111 : Q = 4'b0111;
            4'b1110 : Q = 4'b1111;
            4'b1100 : Q = 4'b1110;
            4'b1000 : Q = 4'b1100;
            4'b0000 : Q = 4'b1000;
            default : Q = 4'b0101;
        endcase

endmodule
